// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // fuzzed params: an address 'from', an array of addresses '_tos', and a uint value 'v'
    // We must deploy a recording helper that implements transferFrom(address,address,uint256)
    // so we can observe how many times C called it and with which args. The rule: for any
    // non-empty _tos, the helper's counter equals _tos.length after transfer returns.
    function testFuzz_property(address from, address a0, address a1, address a2, uint256 v, uint8 len) public {
        // Build a small array of up to 3 addresses from fuzzed inputs to keep test simple
        uint256 l = uint256(len) % 3 + 1; // ensure non-empty and up to 3
        address[] memory tos = new address[](l);
        if (l > 0) tos[0] = a0;
        if (l > 1) tos[1] = a1;
        if (l > 2) tos[2] = a2;

        // Deploy recorder and pass its address as caddress
        Recorder r = new Recorder();

        // call transfer and observe via recorder
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always returns true (does not revert) for any non-empty tos
        // because each external call's success is required; our Recorder always succeeds, so ok must be true.
        // Also, the reference calls transferFrom once per element, so recorder.count() == tos.length.
        // The mutant that starts i=1 will result in recorder.count() == tos.length - 1 for tos.length>=1.

        // Assert the universal property: call succeeded and recorder saw exactly tos.length calls
        assertTrue(ok && r.count() == int256(tos.length));
    }
}

// Recording helper: implements the exact selector transferFrom(address,address,uint256)
contract Recorder {
    // count of how many times called
    int256 private _count = 0;

    // record the last arguments too (not strictly necessary, but harmless)
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        _count += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true; // succeed so C's require(_s) passes
    }

    function count() external view returns (int256) {
        return _count;
    }
}
